import { cn } from '@/registry/ndeko/lib/utils';
import { Wash } from '@/registry/ndeko/ui/wash';

import { APPS, HERO } from './data';
import { Orbit } from './orbit';
import { PromptBox } from './prompt-box';

const STAGE_FADE =
  '[mask-image:linear-gradient(to_bottom,transparent,black_16%,black_84%,transparent)]';

function spokenAppsOf(names: string[]) {
  const last = names[names.length - 1];
  const others = names.slice(0, -1);
  return `${others.join(', ')} and ${last}`;
}

export default function Heroes07() {
  const appNames = APPS.map((app) => app.name);
  const spokenApps = spokenAppsOf(appNames);

  return (
    <section className='@container'>
      <div className='relative isolate overflow-x-clip'>
        <Wash className='h-[28rem]' />
        <div className='mx-auto flex max-w-6xl flex-col items-center px-4 py-16 @2xl:px-6 @2xl:py-24'>
          <div className='flex max-w-3xl flex-col items-center gap-5 text-center'>
            <p className='text-primary-ink text-sm font-medium'>
              {HERO.eyebrow}
            </p>
            <h1 className='text-4xl font-semibold text-balance @2xl:text-5xl'>
              {HERO.title}
            </h1>
            <p className='text-muted-foreground max-w-xl text-base text-pretty'>
              {HERO.description}
            </p>
            <p className='sr-only'>Works with {spokenApps}</p>
          </div>
          <div
            className={cn(
              '@container relative mt-10 h-[22rem] w-full max-w-3xl overflow-hidden @2xl:h-[28rem]',
              STAGE_FADE
            )}
          >
            <Orbit />
            <div className='relative z-10 flex h-full items-center justify-center px-4'>
              <PromptBox />
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

'use client';

import { useMemo, useState } from 'react';

import {
  type AutoplayStep,
  typingSteps,
  useAutoplay,
} from '@/registry/ndeko/hooks/use-autoplay';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';
import { PlugIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import {
  PromptInput,
  PromptInputSubmit,
  PromptInputTextarea,
} from '@/registry/ndeko/ui/chat-prompt-input';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { APPS, HERO, QUESTIONS } from './data';

const BEFORE_TYPING_MS = 350;
const TYPE_MS = 38;
const HOLD_MS = 1600;
const ERASE_MS = 14;
const LOOP_AFTER_MS = 500;

const BOX =
  'dark:bg-card cursor-text rounded-2xl p-2.5 shadow-[0_1px_2px_rgb(0_0_0/0.04),0_16px_40px_-20px_rgb(0_0_0/0.16)]';

function erasingSteps(
  text: string,
  write: (typed: string) => void
): AutoplayStep[] {
  const prefixes = prefixesOf(text);
  const shorter = prefixes.slice(0, -1);
  const remaining = [...shorter.reverse(), ''];
  return remaining.map((typed, index) => {
    const after = keyDelayOf(index, HOLD_MS, ERASE_MS);
    return { after, run: () => write(typed) };
  });
}

function questionSteps(write: (typed: string) => void): AutoplayStep[] {
  const rounds = QUESTIONS.map((question) => [
    ...typingSteps(question, write, {
      startAfter: BEFORE_TYPING_MS,
      characterMs: TYPE_MS,
    }),
    ...erasingSteps(question, write),
  ]);
  return rounds.flat();
}

function placeholderOf(isAutoplaying: boolean) {
  if (isAutoplaying) {
    return '';
  }
  return QUESTIONS[0];
}

function hintKeyOf(isSent: boolean) {
  if (isSent) {
    return 'sent';
  }
  return 'idle';
}

function announcementOf(isSent: boolean) {
  if (isSent) {
    return HERO.sentAnnouncement;
  }
  return '';
}

function caretClassOf(isLive: boolean) {
  if (isLive) {
    return 'animate-pulse';
  }
  return undefined;
}

/** Sits over the empty field and uses its metrics, so the typed question lands where a person's would. */
function TypedQuestion({ text, isLive }: { text: string; isLive: boolean }) {
  return (
    <span
      aria-hidden='true'
      className='text-muted-foreground/75 pointer-events-none absolute inset-0 px-2 py-1.5 text-base leading-normal select-none'
    >
      {text}
      <span
        className={cn(
          'bg-foreground/60 ms-px inline-block h-[1.15em] w-0.5 translate-y-[0.2em] rounded-full',
          caretClassOf(isLive)
        )}
      />
    </span>
  );
}

function Hint({ isSent }: { isSent: boolean }) {
  const key = hintKeyOf(isSent);

  return (
    <Swap swapKey={key} className='text-muted-foreground min-w-0 text-xs'>
      {!isSent && (
        <span className='flex items-center gap-1.5'>
          <PlugIcon className='size-3.5 shrink-0' />
          <span>Reads from {APPS.length} connected apps</span>
        </span>
      )}
      {isSent && (
        <a
          href='#'
          className='text-primary-ink focus-visible:ring-ring/25 rounded-sm outline-none hover:underline focus-visible:ring-[3px]'
        >
          {HERO.sentHint}
        </a>
      )}
    </Swap>
  );
}

export function PromptBox() {
  const [question, setQuestion] = useState('');
  const [typed, setTyped] = useState('');
  const [isSent, setIsSent] = useState(false);
  const steps = useMemo(() => questionSteps(setTyped), []);

  function clearTyped() {
    setTyped('');
  }

  const { ref, isInView, isAutoplaying } = useAutoplay(steps, {
    loopAfter: LOOP_AFTER_MS,
    onReset: clearTyped,
  });
  const placeholder = placeholderOf(isAutoplaying);
  const announcement = announcementOf(isSent);

  function changeQuestion(value: string) {
    setQuestion(value);
    setIsSent(false);
  }

  function send() {
    const hasText = question.trim().length > 0;
    if (!hasText) {
      return;
    }
    setIsSent(true);
  }

  return (
    <div ref={ref} className='w-full max-w-[30rem]'>
      <PromptInput
        value={question}
        onValueChange={changeQuestion}
        onSubmit={send}
        className={BOX}
      >
        <div className='relative'>
          <PromptInputTextarea
            aria-label={HERO.boxLabel}
            placeholder={placeholder}
            className='min-h-[4.5rem] text-base md:text-base'
          />
          {isAutoplaying && <TypedQuestion text={typed} isLive={isInView} />}
        </div>
        <div className='flex min-h-8 items-center justify-between gap-3 ps-2'>
          <Hint isSent={isSent} />
          <PromptInputSubmit sendLabel={HERO.sendLabel} />
        </div>
      </PromptInput>
      <LiveRegion message={announcement} />
    </div>
  );
}

'use client';

import { useInView } from 'motion/react';
import { type CSSProperties, useRef } from 'react';

import { useDocumentVisible } from '@/registry/ndeko/hooks/use-agent-run';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';

import { INNER_RING, OUTER_RING, type Ring } from './data';

const FULL_TURN = 360;

const RING_SIZE: Record<Ring['id'], string> = {
  outer: 'w-[min(35rem,calc(100cqw_-_2.5rem))]',
  inner: 'w-[min(24rem,calc(68.5cqw_-_1.7rem))]',
};

function placeOf(index: number, count: number, startDegrees: number) {
  const degrees = startDegrees + (FULL_TURN / count) * index;
  const radians = (degrees * Math.PI) / 180;
  const left = 50 + 50 * Math.cos(radians);
  const top = 50 + 50 * Math.sin(radians);
  const place: CSSProperties = {
    left: `${left.toFixed(1)}%`,
    top: `${top.toFixed(1)}%`,
  };
  return place;
}

function directionOf(isReversed: boolean) {
  if (isReversed) {
    return 'reverse';
  }
  return 'normal';
}

function playStateOf(isPlaying: boolean) {
  if (isPlaying) {
    return 'running';
  }
  return 'paused';
}

function spinClassOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return undefined;
  }
  return 'animate-spin';
}

type SpinOptions = {
  seconds: number;
  isReversed: boolean;
  isPlaying: boolean;
};

function spinStyleOf({ seconds, isReversed, isPlaying }: SpinOptions) {
  const style: CSSProperties = {
    animationDuration: `${seconds}s`,
    animationDirection: directionOf(isReversed),
    animationPlayState: playStateOf(isPlaying),
  };
  return style;
}

type RingViewProps = {
  ring: Ring;
  isPlaying: boolean;
  shouldReduceMotion: boolean;
};

/** The circle turns one way and each tile turns back the other way at the same speed, so the marks stay upright. */
function RingView({ ring, isPlaying, shouldReduceMotion }: RingViewProps) {
  const spinClass = spinClassOf(shouldReduceMotion);
  const ringStyle = spinStyleOf({
    seconds: ring.turnSeconds,
    isReversed: ring.isReversed,
    isPlaying,
  });
  const tileStyle = spinStyleOf({
    seconds: ring.turnSeconds,
    isReversed: !ring.isReversed,
    isPlaying,
  });
  const count = ring.apps.length;

  return (
    <div
      style={ringStyle}
      className={cn(
        'border-foreground/15 absolute top-1/2 left-1/2 aspect-square -translate-1/2 rounded-full border border-dashed',
        RING_SIZE[ring.id],
        spinClass
      )}
    >
      {ring.apps.map((app, index) => (
        <span
          key={app.id}
          style={placeOf(index, count, ring.startDegrees)}
          className='absolute -translate-x-1/2 -translate-y-1/2'
        >
          <span style={tileStyle} className={cn('block', spinClass)}>
            <BrandTile brand={app.brand} size='2xl' />
          </span>
        </span>
      ))}
    </div>
  );
}

export function Orbit() {
  const ref = useRef<HTMLDivElement>(null);
  const isInView = useInView(ref, { amount: 0.1 });
  const isVisible = useDocumentVisible();
  const shouldReduceMotion = usePrefersReducedMotion();
  const isPlaying = isInView && isVisible;

  return (
    <div ref={ref} aria-hidden='true' className='absolute inset-0'>
      <RingView
        ring={OUTER_RING}
        isPlaying={isPlaying}
        shouldReduceMotion={shouldReduceMotion}
      />
      <RingView
        ring={INNER_RING}
        isPlaying={isPlaying}
        shouldReduceMotion={shouldReduceMotion}
      />
    </div>
  );
}

import type { BrandSlug } from '@/registry/ndeko/lib/brand-logos';

export type App = {
  id: string;
  name: string;
  brand: BrandSlug;
};

export type Ring = {
  id: 'inner' | 'outer';
  apps: App[];
  startDegrees: number;
  turnSeconds: number;
  isReversed: boolean;
};

export const HERO = {
  eyebrow: 'An assistant for teams of two to twenty',
  title: 'Ask one question and get the answer from every app you use',
  description:
    'Type it the way you would say it. The assistant reads your calendar, inbox, tracker and files, then answers with a link to where it found each part.',
  boxLabel: 'Ask a question',
  sendLabel: 'Ask',
  sentHint: 'Sign up to see the answer',
  sentAnnouncement: 'Sign up to see the answer to your question',
};

export const QUESTIONS = [
  'Which invoices are still unpaid this month?',
  'What did I promise to send before Friday?',
  'Move my 3 pm with Amara to tomorrow morning',
  'Summarize the design review thread',
];

export const INNER_RING: Ring = {
  id: 'inner',
  apps: [
    { id: 'calendar', name: 'Google Calendar', brand: 'googlecalendar' },
    { id: 'gmail', name: 'Gmail', brand: 'gmail' },
    { id: 'notion', name: 'Notion', brand: 'notion' },
    { id: 'drive', name: 'Google Drive', brand: 'googledrive' },
  ],
  startDegrees: 45,
  turnSeconds: 90,
  isReversed: false,
};

export const OUTER_RING: Ring = {
  id: 'outer',
  apps: [
    { id: 'linear', name: 'Linear', brand: 'linear' },
    { id: 'github', name: 'GitHub', brand: 'github' },
    { id: 'figma', name: 'Figma', brand: 'figma' },
    { id: 'stripe', name: 'Stripe', brand: 'stripe' },
    { id: 'jira', name: 'Jira', brand: 'jira' },
  ],
  startDegrees: -36,
  turnSeconds: 140,
  isReversed: true,
};

export const APPS: App[] = [...INNER_RING.apps, ...OUTER_RING.apps];
